#include "Conversion.h"
#include "VM.h"
#include <cerrno>
#include <cmath>
#include <cstdlib>
#include <iomanip>
#include <limits>
#include <sstream>
namespace jspp {
bool to_boolean(const js_value&v){switch(v.kind){case JS_VALUE_UNDEFINED:case JS_VALUE_NULL:return false;case JS_VALUE_BOOLEAN:return v.boolean;case JS_VALUE_NUMBER:return v.number!=0&&!std::isnan(v.number);case JS_VALUE_STRING:return !v.string.empty();default:return true;}}
std::string to_string(const js_value&v){std::ostringstream out;switch(v.kind){case JS_VALUE_UNDEFINED:return "undefined";case JS_VALUE_NULL:return "null";case JS_VALUE_BOOLEAN:return v.boolean?"true":"false";case JS_VALUE_NUMBER:if(std::isnan(v.number))return "NaN";if(std::isinf(v.number))return v.number<0?"-Infinity":"Infinity";if(v.number==0)return "0";out<<std::setprecision(15)<<v.number;return out.str();case JS_VALUE_STRING:return v.string;case JS_VALUE_ARRAY:{if(!v.array)return "";std::string text;for(std::size_t i=0;i<v.array->elements.size();++i){if(i)text+=",";const auto&item=v.array->elements[i];if(item.kind!=JS_VALUE_UNDEFINED&&item.kind!=JS_VALUE_NULL)text+=to_string(item);}return text;}case JS_VALUE_FUNCTION:return "function";case JS_VALUE_OBJECT:return "[object Object]";}return "undefined";}
js_value to_primitive(const js_value&v){if(v.kind!=JS_VALUE_OBJECT&&v.kind!=JS_VALUE_ARRAY&&v.kind!=JS_VALUE_FUNCTION)return v;js_value result;result.kind=JS_VALUE_STRING;result.string=to_string(v);return result;}
bool to_number(const js_value&value,double&out){const auto v=to_primitive(value);switch(v.kind){case JS_VALUE_NULL:out=0;return true;case JS_VALUE_BOOLEAN:out=v.boolean?1:0;return true;case JS_VALUE_NUMBER:out=v.number;return true;case JS_VALUE_UNDEFINED:out=std::numeric_limits<double>::quiet_NaN();return true;case JS_VALUE_STRING:{const auto first=v.string.find_first_not_of(" \t\r\n"),last=v.string.find_last_not_of(" \t\r\n");if(first==std::string::npos){out=0;return true;}const auto text=v.string.substr(first,last-first+1);char*end=nullptr;errno=0;out=std::strtod(text.c_str(),&end);if(end!=text.c_str()+text.size())out=std::numeric_limits<double>::quiet_NaN();return true;}default:return false;}}
bool to_property_key(const js_value&v,std::string&out){out=to_string(to_primitive(v));return true;}
bool array_index(const js_value&v,std::size_t&out){std::string key;to_property_key(v,key);if(key.empty())return false;char*end=nullptr;errno=0;const auto value=std::strtoull(key.c_str(),&end,10);if(errno||end!=key.c_str()+key.size()||std::to_string(value)!=key)return false;out=static_cast<std::size_t>(value);return true;}
bool strict_equal(const js_value&a,const js_value&b){if(a.kind!=b.kind)return false;if(a.kind==JS_VALUE_NUMBER)return !std::isnan(a.number)&&!std::isnan(b.number)&&a.number==b.number;if(a.kind==JS_VALUE_BOOLEAN)return a.boolean==b.boolean;if(a.kind==JS_VALUE_STRING)return a.string==b.string;if(a.kind==JS_VALUE_FUNCTION)return a.function==b.function;if(a.kind==JS_VALUE_OBJECT)return a.object==b.object;if(a.kind==JS_VALUE_ARRAY)return a.array==b.array;return true;}
bool abstract_equal(const js_value&a,const js_value&b){if(a.kind==b.kind)return strict_equal(a,b);if((a.kind==JS_VALUE_NULL&&b.kind==JS_VALUE_UNDEFINED)||(a.kind==JS_VALUE_UNDEFINED&&b.kind==JS_VALUE_NULL))return true;if(a.kind==JS_VALUE_BOOLEAN){double n=0;to_number(a,n);js_value x;x.kind=JS_VALUE_NUMBER;x.number=n;return abstract_equal(x,b);}if(b.kind==JS_VALUE_BOOLEAN)return abstract_equal(b,a);if((a.kind==JS_VALUE_NUMBER&&b.kind==JS_VALUE_STRING)||(a.kind==JS_VALUE_STRING&&b.kind==JS_VALUE_NUMBER)){double left=0,right=0;to_number(a,left);to_number(b,right);return !std::isnan(left)&&!std::isnan(right)&&left==right;}if((a.kind==JS_VALUE_OBJECT||a.kind==JS_VALUE_ARRAY||a.kind==JS_VALUE_FUNCTION)&&(b.kind==JS_VALUE_STRING||b.kind==JS_VALUE_NUMBER))return abstract_equal(to_primitive(a),b);if((b.kind==JS_VALUE_OBJECT||b.kind==JS_VALUE_ARRAY||b.kind==JS_VALUE_FUNCTION)&&(a.kind==JS_VALUE_STRING||a.kind==JS_VALUE_NUMBER))return abstract_equal(a,to_primitive(b));return false;}
bool relational_compare(const js_value&a,const js_value&b,int&out){const auto left=to_primitive(a),right=to_primitive(b);if(left.kind==JS_VALUE_STRING&&right.kind==JS_VALUE_STRING){out=left.string<right.string?-1:left.string>right.string?1:0;return true;}double x=0,y=0;if(!to_number(left,x)||!to_number(right,y)||std::isnan(x)||std::isnan(y))return false;out=x<y?-1:x>y?1:0;return true;}
}
